. "$PSScriptRoot\..\shared\Storage.ps1"
param($Request,$TriggerMetadata)
try{$table=Get-TableHandle $env:CERTAMENT_LATEST_TABLE;$rows=@(Get-AzTableRow -table $table -partitionKey 'server');Push-OutputBinding -Name Response -Value (New-JsonResponse 200 @($rows|ForEach-Object{[pscustomobject]@{server=$_.RowKey;customer=$_.Customer;version=$_.Version;status=$_.Status;timestampUtc=$_.TimestampUtc;certificateDaysRemaining=$_.CertificateDaysRemaining;stage=$_.Stage;detail=$_.Detail;notificationStatus=$_.NotificationStatus}}))}catch{Push-OutputBinding -Name Response -Value (New-JsonResponse 500 @{error=$_.Exception.Message})}
